settings.custom_css:
html { scroll-padding-top: 80px; }
selector { transition: min-height .3s ease, box-shadow .3s ease; }
selector .ak-hd-logo img { display: block; transition: width .3s ease; }
/* logo centrado vertical: sin el espacio de línea que dejaba el enlace debajo de la imagen */
selector .ak-hd-logo .elementor-widget-container { line-height: 0; }
selector .ak-hd-logo a { display: block; }
selector.elementor-sticky--effects { --min-height: 70px; box-shadow: 0 6px 20px rgba(7,14,32,.18); }
selector.elementor-sticky--effects .ak-hd-logo img { width: 180px; }
selector .ak-hd-cta .elementor-button { width: 256px; height: 56px; display: inline-flex; align-items: center; justify-content: center; padding: 0; }
selector .ak-hd-nav .elementor-nav-menu--main .elementor-item { white-space: nowrap; }
@media (max-width: 1366px) {
  selector .ak-hd-cta .elementor-button { width: 170px; height: 44px; }
}
@media (max-width: 1366px) {
  selector.elementor-sticky--effects .ak-hd-logo img { width: 160px; }
}
@media (max-width: 767px) { selector .ak-hd-cta { display: none !important; } }
/* menú siempre en una línea, entre el logo y el botón sin chocar */
selector .ak-hd-logo, selector .ak-hd-cta { flex: 0 0 auto; }
selector .ak-hd-nav { flex: 1 1 auto; min-width: 0; }
selector .ak-hd-nav .elementor-nav-menu--main .elementor-nav-menu { flex-wrap: nowrap; justify-content: center; }
selector .ak-hd-nav .elementor-nav-menu--main .elementor-item { padding-left: 0 !important; padding-right: 0 !important; white-space: nowrap; }
@media (min-width: 1281px) and (max-width: 1366px) {
  selector .ak-hd-nav .elementor-nav-menu--main { --e-nav-menu-horizontal-menu-item-margin: calc(32px / 2); }
  selector .ak-hd-nav .elementor-nav-menu--main .elementor-nav-menu > li { margin-left: 16px !important; margin-right: 16px !important; }
}
@media (min-width: 1025px) and (max-width: 1280px) {
  selector { --padding-left: 32px; --padding-right: 32px; }
  selector .ak-hd-logo img { width: 150px; }
  selector .ak-hd-nav .elementor-nav-menu--main { --e-nav-menu-horizontal-menu-item-margin: calc(16px / 2); }
  selector .ak-hd-nav .elementor-nav-menu--main .elementor-nav-menu > li { margin-left: 8px !important; margin-right: 8px !important; }
  selector .ak-hd-nav .elementor-nav-menu--main .elementor-item { font-size: 12px !important; letter-spacing: .4px !important; }
  selector .ak-hd-cta .elementor-button { width: 150px; height: 40px; font-size: 11px !important; }
}
@media (max-width: 1024px) {
  selector .ak-hd-nav { order: 3; }
  selector .ak-hd-cta { margin-left: auto; }
}
@media (max-width: 767px) {
  html { scroll-padding-top: 64px; }
  selector.elementor-sticky--effects { --min-height: 60px; }
  selector.elementor-sticky--effects .ak-hd-logo img { width: 124px; }
}
selector.elementor-sticky--active { width: 100% !important; left: 0 !important; right: 0 !important; }

/* header reducido: el botón baja a la tipografía del menú (15 px) y se achica junto con el header */
selector .ak-hd-cta .elementor-button { transition: width .3s ease, height .3s ease, font-size .3s ease, background-color .3s, color .3s; }
selector.elementor-sticky--effects .ak-hd-cta .elementor-button { width: 210px; height: 46px; font-size: 15px !important; }
@media (max-width: 1366px) {
  selector.elementor-sticky--effects .ak-hd-cta .elementor-button { width: 150px; height: 38px; font-size: 11px !important; }
}
@media (min-width: 1025px) and (max-width: 1280px) {
  selector.elementor-sticky--effects .ak-hd-cta .elementor-button { width: 140px; height: 36px; }
}
